`timescale 1ns/1ps
// 10/24 UI v3: anti-aliased text engine shared by the hall and clinic screens.
//
// Content (glyphs, strings, item table) comes from ROMs generated by
// verification/ui3/ui3_assets.py; the board screen module owns those ROMs and answers four
// small combinational questions: which string/colour a slot shows (slot_*), the value of a
// digit field (field_val), and the first digit glyph of a font (digit_base).
//
// Per scanline, during line y the builder lays out line y+1 into one half of a descriptor
// buffer (ping-pong): for every item whose rows cover y+1 it walks the item's string and
// writes one descriptor per glyph {x, first pixel index, width, column stride, colour}.
// Glyph pixels are stored column-major, so while a glyph is drawn the pixel index only
// grows by the cell height each clock - no multiply or divide in the pixel path.
// The ticker slot (TICKER_SLOT) is laid out at x = TICKER_X0 - scroll, repeats with
// TICKER_GAP, and is clipped to [TICKER_X0, TICKER_X1). A glyph with only one visible column at
// the left clip is not drawn (see `visible`).
// Output: 2-bit coverage and 3-bit colour for the pixel at active x = video_x - H_BLANK,
// valid in the same clock as that pixel (the fetch runs LA = 2 clocks ahead).
module ui_text_engine #(
    parameter integer H_BLANK = 160,
    parameter integer ITEMS = 32,
    parameter integer TICKER_SLOT = 63,
    parameter integer TICKER_X0 = 0, TICKER_X1 = 640, TICKER_GAP = 120
)(
    input wire clk, rst,
    input wire [11:0] video_x,            // raw horizontal counter
    input wire [11:0] pixel_y,            // active y of the current line (wraps in blanking)
    input wire [10:0] scroll,             // ticker offset in pixels, frame-latched by the board
    // item ROM (1-clock read; addresses are combinational, data valid the next clock)
    output wire [5:0] it_addr, input wire [31:0] it_q,
    // slot -> content (combinational, board state)
    output wire [5:0] q_slot,
    input wire [11:0] slot_saddr,         // 0 = nothing
    input wire [2:0] slot_color,
    input wire slot_xov, input wire [9:0] slot_x,
    // string ROM (1-clock read)
    output wire [11:0] s_addr, input wire [11:0] s_q,
    // digit fields
    output wire [7:0] q_field, input wire [3:0] field_val,
    output wire [2:0] q_font, input wire [9:0] digit_base,
    // glyph table (1-clock read): {start[17:0], width[6:0]}
    output wire [9:0] g_addr, input wire [24:0] g_q,
    // glyph pixels (2-clock read, output register), four 2-bit pixels per byte
    output wire [15:0] p_addr, input wire [7:0] p_q,
    output wire [1:0] cov, output wire [2:0] color
);
    localparam integer LA = 2;
    localparam [3:0] B_IDLE = 0, B_ITEM = 1, B_CHECK = 2, B_STR = 3, B_SRD = 4, B_GT = 5, B_EMIT = 6, B_NEXT = 7;

    // ---------------- descriptor buffer: 2 x 64 entries ----------------
    // {x[9:0], addr[17:0], w[6:0], h[6:0], color[2:0]} = 45 bits
    reg [44:0] dbuf [0:127];
    reg bank;                              // half being displayed; the builder writes ~bank
    reg [6:0] wcount;                      // entries written for the line being built
    reg [6:0] dcount;                      // entries of the displayed line
    reg wr_en;
    reg [6:0] wr_addr;
    reg [44:0] wr_data;
    reg [6:0] rd_addr;
    reg [44:0] rd_q;
    always @(posedge clk) begin
        if (wr_en) dbuf[wr_addr] <= wr_data;
        rd_q <= dbuf[rd_addr];
    end

    // ---------------- builder ----------------
    wire line_start = video_x == 12'd0;
    wire [11:0] ny = pixel_y + 12'd1;
    reg [3:0] bst;
    reg [11:0] by;                         // line being built
    reg [5:0] item;
    reg [6:0] ih;                          // item cell height
    reg [8:0] ry;                          // row inside the item
    reg [5:0] islot;
    reg [11:0] sbase;                      // string start
    reg [11:0] sptr;                       // string word being read
    reg signed [11:0] bx;                  // pen x (may be negative for the ticker)
    reg [2:0] bcol;
    reg ticker;
    assign q_slot = islot;
    assign it_addr = item;
    assign s_addr = sptr;
    assign q_field = s_q[7:0];
    assign q_font = s_q[10:8];
    wire [8:0] iy0 = it_q[31:23];
    wire [6:0] iy_h = it_q[22:16];
    wire [9:0] ix0 = it_q[15:6];
    wire [8:0] dy = by[8:0] - iy0;
    wire in_rows = by < 12'd480 && by[8:0] >= iy0 && dy < {2'b00, iy_h};
    wire [9:0] gid = s_q[11] ? digit_base + {6'd0, field_val} : s_q[9:0];
    assign g_addr = gid;                   // sampled at the end of B_GT, data in B_EMIT
    // glyph placement and clipping
    wire [17:0] gstart = g_q[24:7];
    wire [6:0] gw = g_q[6:0];
    wire signed [11:0] gx_end = bx + $signed({5'd0, gw});
    wire signed [11:0] clip_l = ticker ? TICKER_X0 : 12'sd0;
    wire signed [11:0] clip_r = ticker ? TICKER_X1 : 12'sd640;
    // 10/25: at least two visible columns. Playback fetches the next descriptor two clocks after a
    // glyph starts, so a one-column glyph (only possible at the ticker's left clip) followed by an
    // adjacent glyph stalled the whole rest of the line for that frame (the ticker "flickered").
    wire visible = gx_end > clip_l + 12'sd1 && bx < clip_r;
    wire [6:0] off_l = bx < clip_l ? clip_l - bx : 7'd0;
    wire signed [11:0] x_vis = bx < clip_l ? clip_l : bx;
    wire [6:0] w_vis = (gx_end > clip_r ? clip_r - x_vis : gx_end - x_vis);
    wire [17:0] a_vis = gstart + {9'd0, ry} + off_l * ih;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            bst <= B_IDLE; by <= 0; item <= 0; ih <= 0; ry <= 0; islot <= 0; sbase <= 0; sptr <= 0; bx <= 0;
            bcol <= 0; ticker <= 0;
            wcount <= 0; dcount <= 0; bank <= 0; wr_en <= 0; wr_addr <= 0; wr_data <= 0;
        end else begin
            wr_en <= 1'b0;
            if (line_start) begin
                // the line built during the previous line becomes visible; start the next one
                bank <= ~bank; dcount <= wcount; wcount <= 0;
                by <= ny; item <= 0; bst <= B_ITEM;
            end else case (bst)
                B_ITEM: bst <= B_CHECK;                                 // item ROM read
                B_CHECK: begin
                    ih <= iy_h; ry <= dy; islot <= it_q[5:0];
                    ticker <= it_q[5:0] == TICKER_SLOT;
                    bx <= $signed({2'b00, ix0});
                    bst <= in_rows ? B_STR : B_NEXT;
                end
                B_STR: begin
                    // slot_* answer for islot now
                    sbase <= slot_saddr; sptr <= slot_saddr; bcol <= slot_color;
                    if (slot_xov) bx <= $signed({2'b00, slot_x});
                    if (ticker) bx <= TICKER_X0 - $signed({1'b0, scroll});
                    bst <= slot_saddr == 0 ? B_NEXT : B_SRD;
                end
                B_SRD: bst <= B_GT;                                     // string ROM read
                B_GT: begin
                    // string word available: end of string, or look the glyph up (g_addr = gid)
                    if (s_q == 12'hfff) begin
                        if (ticker && bx < TICKER_X1) begin
                            bx <= bx + TICKER_GAP; sptr <= sbase; bst <= B_SRD;
                        end else bst <= B_NEXT;
                    end else bst <= B_EMIT;
                end
                B_EMIT: begin
                    if (visible && wcount != 7'd63) begin
                        wr_en <= 1'b1; wr_addr <= {~bank, wcount[5:0]};
                        wr_data <= {x_vis[9:0], a_vis, w_vis, ih, bcol};
                        wcount <= wcount + 1'b1;
                    end
                    bx <= gx_end;
                    if (gx_end >= clip_r) bst <= B_NEXT;                // rest of the string is off screen
                    else begin sptr <= sptr + 12'd1; bst <= B_SRD; end
                end
                B_NEXT: begin
                    if (item == ITEMS - 1) bst <= B_IDLE;
                    else begin item <= item + 1'b1; bst <= B_ITEM; end
                end
                default: bst <= B_IDLE;
            endcase
        end
    end

    // ---------------- playback (LA clocks ahead of the displayed pixel) ----------------
    wire [11:0] px = video_x - H_BLANK + LA;              // pixel being fetched
    wire fetch_on = video_x >= H_BLANK - LA && video_x < H_BLANK + 640 - LA;
    reg [6:0] ptr;
    reg nd_ok;                                            // rd_q holds descriptor ptr
    reg act;
    reg [17:0] raddr;
    reg [6:0] rcnt, rh;
    reg [2:0] rcolor;
    wire [9:0] nd_x = rd_q[44:35];
    wire [17:0] nd_a = rd_q[34:17];
    wire [6:0] nd_w = rd_q[16:10];
    wire [6:0] nd_h = rd_q[9:3];
    wire start = fetch_on && !act && nd_ok && px[9:0] == nd_x && px < 12'd640;
    wire [17:0] cur = start ? nd_a : raddr;
    wire emit = fetch_on && (start || act);
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            ptr <= 0; nd_ok <= 0; act <= 0; raddr <= 0; rcnt <= 0; rh <= 0; rcolor <= 0; rd_addr <= 0;
        end else begin
            if (line_start) begin
                // descriptor 0 of the line that becomes visible now (bank toggles this clock)
                ptr <= 0; act <= 0; rd_addr <= {~bank, 6'd0};      // bank toggles in this clock
                nd_ok <= 0;
            end else begin
                if (!nd_ok && ptr < dcount && rd_addr == {bank, ptr[5:0]}) nd_ok <= 1'b1;
                if (start) begin
                    raddr <= nd_a + {11'd0, nd_h}; rh <= nd_h; rcnt <= nd_w - 1'b1; rcolor <= rd_q[2:0];
                    act <= nd_w != 7'd1;
                    ptr <= ptr + 1'b1; nd_ok <= 1'b0; rd_addr <= {bank, ptr[5:0] + 6'd1};
                end else if (act) begin
                    raddr <= raddr + {11'd0, rh}; rcnt <= rcnt - 1'b1;
                    if (rcnt == 7'd1) act <= 1'b0;
                end
            end
        end
    end
    // pixel ROM: byte address registered by the ROM, data two clocks later
    assign p_addr = cur[17:2];
    reg [1:0] lane1, lane2;
    reg v1, v2;
    reg [2:0] c1, c2;
    always @(posedge clk or posedge rst) begin
        if (rst) begin lane1 <= 0; lane2 <= 0; v1 <= 0; v2 <= 0; c1 <= 0; c2 <= 0; end
        else begin
            lane1 <= cur[1:0]; lane2 <= lane1;
            v1 <= emit; v2 <= v1;
            c1 <= start ? rd_q[2:0] : rcolor; c2 <= c1;
        end
    end
    assign cov = !v2 ? 2'd0 : lane2 == 2'd0 ? p_q[1:0] : lane2 == 2'd1 ? p_q[3:2] : lane2 == 2'd2 ? p_q[5:4] : p_q[7:6];
    assign color = c2;
endmodule
